   205→      spotifyPlayerActions.open({
   206→        id: album.id,
   207→        title: album.title,
   208→        img: album.img,
   209→        spotifyEmbed: album.spotifyEmbed,
   210→      });
   211→    }
   212→  };
   213→
   214→  const genreCounts = useMemo(() => {
   215→    const counts = new Map<string, number>();
   216→    for (const album of albums) {
   217→      const genre = normalizeGenre(album.style);
   218→      if (!genre) continue;
   219→      counts.set(genre, (counts.get(genre) ?? 0) + 1);
   220→    }
   221→    return counts;
   222→  }, [albums]);
   223→
   224→  // Extract unique genres
   225→  const genres = useMemo(() => {
   226→    return sortGenres(Array.from(genreCounts.keys()));
   227→  }, [genreCounts]);
   228→
   229→  // Filter albums by genre
   230→  const filteredAlbums = useMemo(() => {
   231→    return albums.filter((album) => {
   232→      const albumGenre = normalizeGenre(album.style);
   233→
   234→      const matchesGenre = !selectedGenre || albumGenre === selectedGenre;
   235→      if (!matchesGenre) return false;
   236→      return true;
   237→    });
   238→  }, [albums, selectedGenre]);
   239→
   240→  // Stats - valeurs fixes demandées par Loïc
   241→  const stats = useMemo(
   242→    () => ({
   243→      total: 20,
   244→      genres: "∞",
   245→      collaborations: albums.filter((a) => a.collabName).length,
   246→      years: "2018 - 2026",
   247→    }),
   248→    [albums]
   249→  );
   250→
   251→  return (
   252→    <div className="min-h-screen bg-neo-bg text-neo-text font-sans selection:bg-neo-text selection:text-neo-accent overflow-x-hidden">
   253→      <GridBackground withAccentGlow />
   254→      <NeoNavbar />
   255→
   256→      <main className="relative z-10 pt-16 md:pt-20">
   257→        {/* Hero */}
   258→        <NeoHeroSection
   259→          badgeNumber="04"
   260→          badge={t("hero.badge")}
   261→          title={t("hero.title")}
   262→          description={t("hero.description")}
   263→          fullViewport
   264→        >
   265→          <div className="flex flex-wrap gap-4">
   266→            <BrutalistButton
   267→              variant="primary"
   268→              size="lg"
   269→              icon={<Music className="w-5 h-5" />}
   270→              onClick={() =>
   271→                document.getElementById("albums-grid")?.scrollIntoView({ behavior: "smooth" })
   272→              }
   273→            >
   274→              {t("hero.cta")}
   275→            </BrutalistButton>
   276→            <Link href="/contact">
   277→              <BrutalistButton variant="secondary" size="lg">
   278→                {t("hero.ctaSecondary")}
   279→              </BrutalistButton>
   280→            </Link>
   281→          </div>
   282→        </NeoHeroSection>
   283→
   284→        {/* Stats Bar */}
   285→        <section className="border-y-4 border-neo-border bg-neo-text text-neo-text-inverse py-12">
   286→          <div className="container mx-auto px-4 md:px-6">
   287→            <div className="grid grid-cols-2 md:grid-cols-4 gap-8 text-center">
   288→              {[
   289→                { val: stats.total.toString(), label: t("stats.total") },
   290→                { val: stats.genres.toString(), label: t("stats.genres") },
   291→                { val: stats.collaborations.toString(), label: t("stats.collaborations") },
   292→                { val: stats.years, label: t("stats.period") },
   293→              ].map((stat, i) => (
   294→                <div key={i} className="flex flex-col items-center">
   295→                  <span className="text-4xl md:text-5xl font-black text-neo-accent tracking-tighter">
   296→                    {stat.val}
   297→                  </span>
   298→                  <span className="font-mono text-xs uppercase tracking-widest mt-2 opacity-60">
   299→                    {stat.label}
   300→                  </span>
   301→                </div>
   302→              ))}
   303→            </div>
   304→          </div>
   305→        </section>
   306→
   307→        {/* Filters */}
   308→        <section className="py-8 border-b-2 border-neo-border sticky top-[72px] bg-neo-bg z-30">
   309→          <div className="container mx-auto px-4 md:px-6">
   310→            <div className="flex flex-wrap gap-2">
   311→              <button
   312→                onClick={() => setSelectedGenre(null)}
   313→                className={`px-4 py-2 font-mono text-xs font-bold uppercase border-2 border-neo-border transition-all ${
   314→                  !selectedGenre
   315→                    ? "bg-neo-accent text-neo-text-inverse border-neo-accent"
   316→                    : "bg-neo-surface hover:bg-neo-accent hover:text-neo-text-inverse hover:border-neo-accent"
   317→                }`}
   318→              >
   319→                {t("filterAll")} ({albums.length})
   320→              </button>
   321→              {genres.map((genre) => (
   322→                <button
   323→                  key={genre}
   324→                  onClick={() => setSelectedGenre(genre)}
   325→                  className={`px-4 py-2 font-mono text-xs font-bold uppercase border-2 border-neo-border transition-all ${
   326→                    selectedGenre === genre
   327→                      ? "bg-neo-accent text-neo-text-inverse border-neo-accent"
   328→                      : "bg-neo-surface hover:bg-neo-accent hover:text-neo-text-inverse hover:border-neo-accent"
   329→                  }`}
   330→                >
   331→                  {genre} ({genreCounts.get(genre) ?? 0})
   332→                </button>
   333→              ))}
   334→            </div>
   335→          </div>
   336→        </section>
   337→
   338→        {/* Albums Grid */}
   339→        <section id="albums-grid" className="py-16">
   340→          <div className="container mx-auto px-4 md:px-6">
   341→            <AnimatePresence mode="wait">
   342→              <motion.div
   343→                key={selectedGenre || "all"}
