   348→                className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-16"
   349→              >
   350→                {filteredAlbums.length > 0 ? (
   351→                  filteredAlbums.map((album) => (
   352→                    <AlbumCard
   353→                      key={album.id}
   354→                      album={album}
   355→                      onPlayClick={handlePlayClick}
   356→                      normalizeGenre={normalizeGenre}
