                      </div>
                    </div>
                  </div>
                </NeoCard>
              </Link>
            </div>

            {/* Back to albums link */}
            <div className="mt-8 text-center">
              <Link
                href="/albums"
                className="inline-flex items-center gap-2 font-mono text-sm font-bold uppercase hover:text-neo-accent transition-colors"
              >
                <ArrowLeft className="w-4 h-4" />
                {t("backToAlbums")}
              </Link>
            </div>
          </motion.section>
        </div>
      </main>

      <NeoFooter />
    </div>
  );
}

